INSERT INTO bm_rule (rule_code,name,concept_code,rule_type,expression,severity,owner,status,version,engine) VALUES ('R01','库存、承诺与合格可用分离','Lot','CONSTRAINT','只有当前用途、证据版本、收货、性能检验、来源核验及授权放行均成立的数量进入合格可用量。','HIGH','仓库负责人','DRAFT',1,'CONTRACT');
INSERT INTO bm_rule (rule_code,name,concept_code,rule_type,expression,severity,owner,status,version,engine) VALUES ('R02','保护已冻结预留','Reservation','CONSTRAINT','有效冻结预留不得挪给其他需求；同批有效占用合计不得超过实物量。','HIGH','仓库负责人','DRAFT',1,'CONTRACT');
INSERT INTO bm_rule (rule_code,name,concept_code,rule_type,expression,severity,owner,status,version,engine) VALUES ('R03','证据绑定确切版本与范围','Evidence','CONSTRAINT','证据主体、场地、交货行、批次、数量及有效期逐项核验；范围证书不能代替本次交易证书。','HIGH','质量负责人','DRAFT',1,'CONTRACT');
INSERT INTO bm_rule (rule_code,name,concept_code,rule_type,expression,severity,owner,status,version,engine) VALUES ('R04','回执幂等与超收拒绝','ActionReceipt','CONSTRAINT','同business_id同内容回查原回执，不同内容拒绝；累计收货不超过签署数量。','HIGH','仓库负责人','DRAFT',1,'CONTRACT');
INSERT INTO bm_rule (rule_code,name,concept_code,rule_type,expression,severity,owner,status,version,engine) VALUES ('R05','旧需求或承诺批准失效','Demand','CONSTRAINT','数量、交期或条件变化后重新审核；旧签署和库存占用保留到释放回执。','HIGH','采购负责人','DRAFT',1,'CONTRACT');
INSERT INTO bm_rule (rule_code,name,concept_code,rule_type,expression,severity,owner,status,version,engine) VALUES ('R06','新鲜度与来源冲突阻断','Demand','CONSTRAINT','过期快照、未裁决来源冲突不能作为新分配或新批准的依据。','HIGH','销售 / PMC','DRAFT',1,'CONTRACT');
INSERT INTO bm_rule (rule_code,name,concept_code,rule_type,expression,severity,owner,status,version,engine) VALUES ('R07','结清、付款与齐套分别计算','ProcurementSettlement','CONSTRAINT','采购结清不证明付款，付款不证明收货，承诺不证明实际齐套。','HIGH','财务负责人','DRAFT',1,'CONTRACT');
INSERT INTO bm_rule (rule_code,name,concept_code,rule_type,expression,severity,owner,status,version,engine) VALUES ('R08','单位与金额不隐式转换','UomConversion','CONSTRAINT','不同物料单位、币种不得直接求和；金额以整数最小货币单位加币种记录。','HIGH','主数据管理员','DRAFT',1,'CONTRACT');
INSERT INTO bm_rule (rule_code,name,concept_code,rule_type,expression,severity,owner,status,version,engine) VALUES ('R09','BOM版本与工单绑定','BomRevision','CONSTRAINT','工单冻结批准BOM版本；工程变更保留旧版，重新评估在制与采购影响。','HIGH','生产负责人','DRAFT',1,'CONTRACT');
INSERT INTO bm_rule (rule_code,name,concept_code,rule_type,expression,severity,owner,status,version,engine) VALUES ('R10','投入产出谱系有依据','LotGenealogy','CONSTRAINT','分拆、合并与损耗均有实际事件依据；不能凭关系路径推断物料物理混配。','HIGH','生产负责人','DRAFT',1,'CONTRACT');
INSERT INTO bm_rule (rule_code,name,concept_code,rule_type,expression,severity,owner,status,version,engine) VALUES ('R11','发票付款分配守恒','Invoice','CONSTRAINT','同币种有效分配不超过发票或付款余额；冲销保留原记录，未分配余额单独显示。','HIGH','财务负责人','DRAFT',1,'CONTRACT');
INSERT INTO bm_rule (rule_code,name,concept_code,rule_type,expression,severity,owner,status,version,engine) VALUES ('R12','客户签收独立于发运','Delivery','CONSTRAINT','以实际签收与验收回执判交付，不能以物流发运状态冒充客户验收。','HIGH','物流负责人','DRAFT',1,'CONTRACT');
INSERT INTO bm_rule (rule_code,name,concept_code,rule_type,expression,severity,owner,status,version,engine) VALUES ('R13','处置授权不直接改库存','Disposition','CONSTRAINT','范围确认、质量授权、WMS执行与结案分开；实际退供回执才扣库存。','HIGH','售后 / 质量','DRAFT',1,'CONTRACT');
INSERT INTO bm_rule (rule_code,name,concept_code,rule_type,expression,severity,owner,status,version,engine) VALUES ('R14','Agent建议与授权写入分离','DecisionRecord','CONSTRAINT','只读工具不给业务写权限；批准绑定当前身份、版本、幂等键与业务守卫。','HIGH','业务审核人 / 模型管理员','DRAFT',1,'CONTRACT');
INSERT INTO bm_metric (metric_code,name,definition,formula,concept_code,owner) VALUES ('M01','实际材料缺口','现有演示可核对，按需求行而非全库存计算；单位：kg','max(0, 当前需求量 - 当前用途合格可用量)','Demand','销售 / PMC');
INSERT INTO bm_metric (metric_code,name,definition,formula,concept_code,owner) VALUES ('M02','其他订单保护量','现有演示为O2保护范围，不冒充全企业口径；单位：kg','其他需求的有效冻结预留合计','Reservation','仓库负责人');
INSERT INTO bm_metric (metric_code,name,definition,formula,concept_code,owner) VALUES ('M03','供应商按时足量交付率','待源接入；退货、改期及分母为0的口径需owner确认；单位：%','按批准交期足量接收的到期采购行数 / 到期采购行数','GoodsReceipt','仓库负责人');
INSERT INTO bm_metric (metric_code,name,definition,formula,concept_code,owner) VALUES ('M04','一次检验合格率','待完整检验事件；不能由当前批次状态倒推历史；单位：%','首次检验合格批次数 / 首次检验完成批次数','Inspection','质量负责人');
INSERT INTO bm_metric (metric_code,name,definition,formula,concept_code,owner) VALUES ('M05','生产良品率','待源接入；相同物料单位、工序和统计窗口；单位：%','实际良品产出 / (实际良品产出 + 实际报废产出)','ProductionReport','生产负责人');
INSERT INTO bm_metric (metric_code,name,definition,formula,concept_code,owner) VALUES ('M06','客户按时验收率','待源接入；发运不能当验收；单位：%','约定交期内验收完成订单行数 / 到期订单行数','CustomerAcceptance','物流负责人');
INSERT INTO bm_metric (metric_code,name,definition,formula,concept_code,owner) VALUES ('M07','应付未分配余额','待源接入；币种分组、冲销另计，不隐式换汇；单位：minor_currency','有效付款额 - 同币种有效付款分配额','Payment','财务负责人');
INSERT INTO bm_metric (metric_code,name,definition,formula,concept_code,owner) VALUES ('M08','处置关闭周期','待全生命周期时间戳；未结案列在途账龄而非0；单位：minute','实际结案时点 - 处置创建时点','Disposition','售后 / 质量');
